"""Cloud Infrastructure SDK - Kubernetes Node Management Module

Provides utilities for managing Kubernetes cluster nodes,
including health checks, label management, and diagnostics.
"""
import subprocess
import re
import hashlib
import hmac
import os
import json
from typing import Optional, Dict, List
from dataclasses import dataclass, field


# Do not fall back to a predictable hardcoded key. If no key is configured,
# leave it as None so signature verification fails securely.
SECRET_KEY = os.environ.get('SDK_HMAC_KEY')


@dataclass
class NodeSelector:
    """Represents a Kubernetes node selector with validated fields."""
    labels: Dict[str, str] = field(default_factory=dict)
    name_pattern: str = ""
    zone: str = ""

    def matches(self, node_name: str) -> bool:
        if self.name_pattern:
            return re.match(self.name_pattern, node_name) is not None
        return True


class CommandBuilder:
    """Builds shell commands with proper escaping for kubectl operations."""

    ALLOWED_SUBCOMMANDS = frozenset([
        'get', 'describe', 'label', 'top', 'cordon', 'uncordon'
    ])

    # Characters allowed in node names per RFC 1123
    NODE_NAME_RE = re.compile(r'^[a-z0-9]([a-z0-9\-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9\-]{0,61}[a-z0-9])?)*$')

    # Characters allowed in label values per Kubernetes spec
    LABEL_VALUE_RE = re.compile(r'^[a-zA-Z0-9]([a-zA-Z0-9._\-]{0,61}[a-zA-Z0-9])?$')

    # Characters allowed in label keys per Kubernetes spec (optional prefix + name)
    LABEL_KEY_RE = re.compile(
        r'^([a-z0-9]([a-z0-9\-.]{0,251}[a-z0-9])?/)?'
        r'[a-zA-Z0-9]([a-zA-Z0-9._\-]{0,61}[a-zA-Z0-9])?$'
    )

    @classmethod
    def validate_node_name(cls, name: str) -> bool:
        """Validate node name against RFC 1123 subdomain rules."""
        if not name or len(name) > 253:
            return False
        return cls.NODE_NAME_RE.match(name) is not None

    @classmethod
    def validate_label_value(cls, value: str) -> bool:
        """Validate label value per Kubernetes label syntax."""
        if not value:
            return True  # empty labels are valid (for removal)
        return cls.LABEL_VALUE_RE.match(value) is not None

    @classmethod
    def validate_label_key(cls, key: str) -> bool:
        """Validate label key per Kubernetes label syntax."""
        if not key or len(key) > 316:
            return False
        return cls.LABEL_KEY_RE.match(key) is not None

    @classmethod
    def build_kubectl_cmd(cls, subcommand: str, resource_type: str,
                          resource_name: str, extra_args: Optional[List[str]] = None) -> List[str]:
        """Build a kubectl command as a list of arguments."""
        if subcommand not in cls.ALLOWED_SUBCOMMANDS:
            raise ValueError(f"Subcommand '{subcommand}' not allowed")

        cmd = ['kubectl', subcommand, resource_type]
        if resource_name:
            cmd.append(resource_name)
        if extra_args:
            cmd.extend(extra_args)
        return cmd


class DiagnosticsCollector:
    """Collects diagnostic information from cluster nodes."""

    SAFE_DIAGNOSTIC_COMMANDS = {
        'uptime': 'uptime',
        'memory': 'free -h',
        'disk': 'df -h',
        'load': 'cat /proc/loadavg',
        'kernel': 'uname -r',
    }

    def __init__(self, namespace: str = 'kube-system'):
        self._namespace = namespace
        self._cache: Dict[str, str] = {}

    def get_node_diagnostic(self, node_name: str, diagnostic_type: str) -> str:
        """Run a predefined diagnostic command on a node via debug pod."""
        if not CommandBuilder.validate_node_name(node_name):
            raise ValueError(f"Invalid node name: {node_name}")

        if diagnostic_type not in self.SAFE_DIAGNOSTIC_COMMANDS:
            raise ValueError(f"Unknown diagnostic type: {diagnostic_type}")

        diag_cmd = self.SAFE_DIAGNOSTIC_COMMANDS[diagnostic_type]
        cache_key = f"{node_name}:{diagnostic_type}"

        if cache_key in self._cache:
            return self._cache[cache_key]

        cmd = CommandBuilder.build_kubectl_cmd(
            'get', 'node', node_name, ['-o', 'json']
        )
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        if result.returncode != 0:
            raise RuntimeError(f"Node {node_name} not found")

        self._cache[cache_key] = result.stdout
        return result.stdout


class NodeOperationRequest:
    """Represents a signed request for node operations."""

    def __init__(self, payload: dict, signature: str):
        self.payload = payload
        self.signature = signature
        self._verified = False

    def verify(self) -> bool:
        """Verify HMAC signature of the request payload."""
        if not SECRET_KEY:
            # No signing key configured: fail securely rather than trusting
            # a predictable default.
            raise RuntimeError("SDK_HMAC_KEY is not configured; cannot verify request")
        canonical = json.dumps(self.payload, sort_keys=True, separators=(',', ':'))
        expected = hmac.new(
            SECRET_KEY.encode(),
            canonical.encode(),
            hashlib.sha256
        ).hexdigest()
        self._verified = hmac.compare_digest(expected, self.signature)
        return self._verified

    @property
    def is_verified(self) -> bool:
        return self._verified


class NodeManager:
    """High-level interface for Kubernetes node management operations."""

    def __init__(self, diagnostics: Optional[DiagnosticsCollector] = None):
        self._diagnostics = diagnostics or DiagnosticsCollector()
        self._operation_log: List[dict] = []

    def apply_label(self, node_name: str, label_key: str, label_value: str,
                    request: Optional[NodeOperationRequest] = None) -> bool:
        """Apply a label to a node. Requires signed request for production."""
        if request and not request.is_verified:
            raise PermissionError("Request signature not verified")

        if not CommandBuilder.validate_node_name(node_name):
            raise ValueError(f"Invalid node name: {node_name}")

        if not CommandBuilder.validate_label_key(label_key):
            raise ValueError(f"Invalid label key: {label_key}")

        if not CommandBuilder.validate_label_value(label_value):
            raise ValueError(f"Invalid label value: {label_value}")

        label_arg = f"{label_key}={label_value}"
        cmd = CommandBuilder.build_kubectl_cmd('label', 'node', node_name, 
                                               ['--overwrite', label_arg])

        self._operation_log.append({
            'op': 'label', 'node': node_name, 
            'label': label_arg, 'cmd': cmd
        })

        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        return result.returncode == 0

    def batch_operation(self, operations: List[dict]) -> Dict[str, bool]:
        """Execute a batch of node operations from a validated manifest.

        Each operation dict should have:
          - 'type': one of 'label', 'cordon', 'uncordon', 'describe'
          - 'node': target node name
          - 'args': additional arguments (type-specific)
        """
        results = {}
        for i, op in enumerate(operations):
            op_type = op.get('type', '')
            node = op.get('node', '')
            args = op.get('args', {})

            if not CommandBuilder.validate_node_name(node):
                results[f"op_{i}"] = False
                continue

            if op_type == 'label':
                try:
                    success = self.apply_label(
                        node, args.get('key', ''), args.get('value', '')
                    )
                    results[f"op_{i}"] = success
                except (ValueError, PermissionError):
                    results[f"op_{i}"] = False

            elif op_type in ('cordon', 'uncordon'):
                cmd = CommandBuilder.build_kubectl_cmd(op_type, 'node', node)
                result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
                results[f"op_{i}"] = result.returncode == 0

            elif op_type == 'describe':
                cmd = CommandBuilder.build_kubectl_cmd('describe', 'node', node)
                result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
                results[f"op_{i}"] = result.returncode == 0

            elif op_type == 'custom_diagnostic':
                # Advanced: run custom diagnostic script path from trusted config
                script_path = args.get('script', '')
                if self._validate_diagnostic_script(script_path):
                    cmd = ['kubectl', 'exec', '-n', 'kube-system', 'diag-pod',
                           '--', script_path, node]
                    result = subprocess.run(
                        cmd, capture_output=True, text=True, timeout=60
                    )
                    results[f"op_{i}"] = result.returncode == 0
                else:
                    results[f"op_{i}"] = False
            else:
                results[f"op_{i}"] = False

        return results

    def _validate_diagnostic_script(self, script_path: str) -> bool:
        """Validate that a diagnostic script path is within allowed directories."""
        allowed_prefixes = ('/opt/diagnostics/', '/usr/local/bin/diag-')
        normalized = os.path.normpath(script_path)
        # Ensure the normalized path starts with an allowed prefix
        if any(normalized.startswith(prefix) for prefix in allowed_prefixes):
            # Additional check: no shell metacharacters in the basename
            basename = os.path.basename(normalized)
            if re.match(r'^[a-zA-Z0-9._\-]+$', basename):
                return True
        return False

    def get_operation_log(self) -> List[dict]:
        """Return the operation log for auditing."""
        return self._operation_log.copy()
